from pathlib import Path
p=Path('app/src/main/java/com/tufanprintops/uretimperformans/MainActivity.java')
s=p.read_text(encoding='utf-8')

# Native direct-PDF generation: bypass Android print preview (which can hang at "Hazırlanıyor").
imports={
'import android.os.CancellationSignal;':'import android.os.Bundle;\n',
'import android.os.ParcelFileDescriptor;':'import android.os.CancellationSignal;\n',
'import android.print.PrintAttributes;':'import android.print.PrintManager;\n',
'import android.print.PrintDocumentAdapter;':'import android.print.PrintAttributes;\n',
'import android.print.PrintDocumentInfo;':'import android.print.PrintDocumentAdapter;\n',
'import android.print.PageRange;':'import android.print.PrintDocumentInfo;\n',
}
for line,after in imports.items():
    if line not in s:
        if after not in s: raise SystemExit('import anchor missing: '+after)
        s=s.replace(after,after+line+'\n',1)

if 'REQ_SAVE_PDF = 2203' not in s:
    s=s.replace('    private static final int REQ_SAVE_FILE = 2202;\n','    private static final int REQ_SAVE_FILE = 2202;\n    private static final int REQ_SAVE_PDF = 2203;\n',1)

field_anchor='    private String pendingSaveMime;\n'
field_add='''    private File pendingPdfFile;\n    private String pendingPdfName;\n'''
if 'private File pendingPdfFile;' not in s:
    if field_anchor not in s: raise SystemExit('field anchor missing')
    s=s.replace(field_anchor,field_anchor+field_add,1)

# Replace only the last bridge method (printHtml), keep the AndroidBridge closing brace intact.
start=s.find('        @JavascriptInterface\n        public boolean printHtml(String title, String html) {')
if start<0:
    start=s.find('        @JavascriptInterface\n        public void printHtml(String title, String html) {')
if start<0: raise SystemExit('printHtml start not found')
bridge_close=s.find('\n    }\n\n    private String sanitizeFileName',start)
if bridge_close<0: raise SystemExit('AndroidBridge close marker not found')
new_method='''        @JavascriptInterface\n        public boolean printHtml(String title, String html) {\n            final String jobTitle = (title == null || title.trim().isEmpty()) ? "Üretim Performans Raporu" : title.trim();\n            final String safeHtml = (html == null || html.trim().isEmpty()) ? "<html><body><h2>Rapor içeriği boş.</h2></body></html>" : html;\n            runOnUiThread(() -> preparePdfWebView(jobTitle, safeHtml));\n            return true;\n        }\n'''
s=s[:start]+new_method+s[bridge_close:]

helper_marker='    private String sanitizeFileName(String n) {'
if helper_marker not in s: raise SystemExit('sanitize helper marker missing')
helpers='''    private void notifyJs(String js) {\n        if (webView != null) webView.post(() -> webView.evaluateJavascript(js, null));\n    }\n\n    private void cleanupPrintWebView() {\n        if (printWebView != null) {\n            try {\n                if (rootLayout != null) rootLayout.removeView(printWebView);\n                printWebView.stopLoading();\n                printWebView.destroy();\n            } catch (Exception ignored) {}\n            printWebView = null;\n        }\n    }\n\n    private void preparePdfWebView(String jobTitle, String safeHtml) {\n        try {\n            notifyJs("if(window.nativePrintPreparing){nativePrintPreparing();}");\n            cleanupPrintWebView();\n            final WebView pv = new WebView(MainActivity.this);\n            printWebView = pv;\n            pv.setBackgroundColor(Color.WHITE);\n            WebSettings ps = pv.getSettings();\n            ps.setJavaScriptEnabled(false);\n            ps.setDomStorageEnabled(false);\n            ps.setLoadWithOverviewMode(true);\n            ps.setUseWideViewPort(true);\n            ps.setOffscreenPreRaster(true);\n            if (rootLayout == null) throw new IllegalStateException("PDF görünüm kapsayıcısı hazır değil");\n            FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT);\n            rootLayout.addView(pv, 0, lp);\n            final boolean[] started = {false};\n            final Runnable startPdf = () -> {\n                if (started[0] || printWebView != pv || isFinishing()) return;\n                started[0] = true;\n                pv.postDelayed(() -> writeWebViewToPdf(jobTitle, pv), 650);\n            };\n            pv.setWebViewClient(new WebViewClient() {\n                @Override public void onPageCommitVisible(WebView view, String url) { view.postDelayed(startPdf, 180); }\n                @Override public void onPageFinished(WebView view, String url) { view.postDelayed(startPdf, 180); }\n            });\n            pv.loadDataWithBaseURL("https://print.local/", safeHtml, "text/html", "UTF-8", null);\n            pv.postDelayed(startPdf, 2500);\n            pv.postDelayed(() -> {\n                if (!started[0] && printWebView == pv) {\n                    started[0] = true;\n                    notifyJs("if(window.nativePrintFailed){nativePrintFailed('PDF görünümü hazırlanamadı.');}");\n                    cleanupPrintWebView();\n                }\n            }, 6000);\n        } catch (Exception ex) {\n            String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n            notifyJs("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}");\n            cleanupPrintWebView();\n        }\n    }\n\n    private void writeWebViewToPdf(String jobTitle, WebView pv) {\n        final boolean[] finished = {false};\n        final PrintDocumentAdapter adapter;\n        try {\n            adapter = pv.createPrintDocumentAdapter(jobTitle);\n        } catch (Exception ex) {\n            String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n            notifyJs("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}");\n            cleanupPrintWebView();\n            return;\n        }\n        final PrintAttributes attrs = new PrintAttributes.Builder()\n                .setMediaSize(PrintAttributes.MediaSize.ISO_A4.asLandscape())\n                .setResolution(new PrintAttributes.Resolution("upm_pdf", "Üretim Performans PDF", 300, 300))\n                .setMinMargins(new PrintAttributes.Margins(300, 300, 300, 300))\n                .setColorMode(PrintAttributes.COLOR_MODE_COLOR)\n                .build();\n        final CancellationSignal cancel = new CancellationSignal();\n        try { adapter.onStart(); } catch (Exception ignored) {}\n        adapter.onLayout(null, attrs, cancel, new PrintDocumentAdapter.LayoutResultCallback() {\n            @Override public void onLayoutFinished(PrintDocumentInfo info, boolean changed) {\n                if (finished[0]) return;\n                try {\n                    final File out = new File(getCacheDir(), "upm-report-" + System.currentTimeMillis() + ".pdf");\n                    final ParcelFileDescriptor pfd = ParcelFileDescriptor.open(out, ParcelFileDescriptor.MODE_CREATE | ParcelFileDescriptor.MODE_TRUNCATE | ParcelFileDescriptor.MODE_READ_WRITE);\n                    adapter.onWrite(new PageRange[]{PageRange.ALL_PAGES}, pfd, cancel, new PrintDocumentAdapter.WriteResultCallback() {\n                        private void closePfd() { try { pfd.close(); } catch (Exception ignored) {} }\n                        private void finishAdapter() { try { adapter.onFinish(); } catch (Exception ignored) {} }\n                        @Override public void onWriteFinished(PageRange[] pages) {\n                            if (finished[0]) return; finished[0] = true; closePfd(); finishAdapter();\n                            runOnUiThread(() -> {\n                                if (!out.exists() || out.length() < 256) {\n                                    notifyJs("if(window.nativePrintFailed){nativePrintFailed('PDF dosyası oluşturulamadı.');}");\n                                    try { out.delete(); } catch (Exception ignored) {}\n                                    cleanupPrintWebView(); return;\n                                }\n                                pendingPdfFile = out;\n                                String base = sanitizeFileName(jobTitle);\n                                pendingPdfName = base.toLowerCase().endsWith(".pdf") ? base : base + ".pdf";\n                                cleanupPrintWebView();\n                                notifyJs("if(window.nativePrintStarted){nativePrintStarted();}");\n                                Intent intent = new Intent(Intent.ACTION_CREATE_DOCUMENT);\n                                intent.addCategory(Intent.CATEGORY_OPENABLE);\n                                intent.setType("application/pdf");\n                                intent.putExtra(Intent.EXTRA_TITLE, pendingPdfName);\n                                try { startActivityForResult(intent, REQ_SAVE_PDF); }\n                                catch (Exception ex) {\n                                    String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n                                    notifyJs("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}");\n                                }\n                            });\n                        }\n                        @Override public void onWriteFailed(CharSequence error) {\n                            if (finished[0]) return; finished[0] = true; closePfd(); finishAdapter();\n                            runOnUiThread(() -> { notifyJs("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(error == null ? "PDF yazımı başarısız." : error.toString()) + ");}"); cleanupPrintWebView(); try { out.delete(); } catch (Exception ignored) {} });\n                        }\n                        @Override public void onWriteCancelled() {\n                            if (finished[0]) return; finished[0] = true; closePfd(); finishAdapter();\n                            runOnUiThread(() -> { notifyJs("if(window.nativePrintFailed){nativePrintFailed('PDF oluşturma iptal edildi.');}"); cleanupPrintWebView(); try { out.delete(); } catch (Exception ignored) {} });\n                        }\n                    });\n                } catch (Exception ex) {\n                    if (finished[0]) return; finished[0] = true; try { adapter.onFinish(); } catch (Exception ignored) {}\n                    String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n                    runOnUiThread(() -> { notifyJs("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}"); cleanupPrintWebView(); });\n                }\n            }\n            @Override public void onLayoutFailed(CharSequence error) {\n                if (finished[0]) return; finished[0] = true; try { adapter.onFinish(); } catch (Exception ignored) {}\n                runOnUiThread(() -> { notifyJs("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(error == null ? "PDF sayfa düzeni hazırlanamadı." : error.toString()) + ");}"); cleanupPrintWebView(); });\n            }\n            @Override public void onLayoutCancelled() {\n                if (finished[0]) return; finished[0] = true; try { adapter.onFinish(); } catch (Exception ignored) {}\n                runOnUiThread(() -> { notifyJs("if(window.nativePrintFailed){nativePrintFailed('PDF sayfa düzeni iptal edildi.');}"); cleanupPrintWebView(); });\n            }\n        }, Bundle.EMPTY);\n        pv.postDelayed(() -> {\n            if (!finished[0] && printWebView == pv) {\n                finished[0] = true; try { cancel.cancel(); adapter.onFinish(); } catch (Exception ignored) {}\n                notifyJs("if(window.nativePrintFailed){nativePrintFailed('PDF oluşturma zaman aşımına uğradı.');}");\n                cleanupPrintWebView();\n            }\n        }, 20000);\n    }\n\n'''
if 'private void preparePdfWebView' not in s:
    s=s.replace(helper_marker,helpers+helper_marker,1)

# Save generated PDF via Android document picker.
activity_marker='''        if (requestCode == REQ_SAVE_FILE) {'''
pdf_result='''        if (requestCode == REQ_SAVE_PDF) {\n            boolean ok = false;\n            File source = pendingPdfFile;\n            String name = pendingPdfName;\n            if (resultCode == RESULT_OK && data != null && data.getData() != null && source != null && source.exists()) {\n                try (FileInputStream in = new FileInputStream(source); OutputStream out = getContentResolver().openOutputStream(data.getData(), "w")) {\n                    if (out != null) { byte[] buf = new byte[8192]; int n; while ((n = in.read(buf)) >= 0) out.write(buf, 0, n); out.flush(); ok = true; }\n                } catch (Exception ignored) {}\n            }\n            if (source != null) try { source.delete(); } catch (Exception ignored) {}\n            pendingPdfFile = null; pendingPdfName = null;\n            final boolean savedPdf = ok; final String savedPdfName = name;\n            notifyJs(savedPdf ? "if(window.nativePdfSaved){nativePdfSaved(" + jsQuote(savedPdfName) + ");}" : "if(window.nativePdfSaveCancelled){nativePdfSaveCancelled();}");\n            return;\n        }\n'''+activity_marker
if 'requestCode == REQ_SAVE_PDF' not in s:
    if activity_marker not in s: raise SystemExit('onActivityResult save-file marker missing')
    s=s.replace(activity_marker,pdf_result,1)

# Ensure temp PDF is removed on Activity teardown.
destroy_old='''        if (printWebView != null) printWebView.destroy();\n        super.onDestroy();'''
destroy_new='''        cleanupPrintWebView();\n        if (pendingPdfFile != null) { try { pendingPdfFile.delete(); } catch (Exception ignored) {} pendingPdfFile = null; }\n        super.onDestroy();'''
if destroy_old in s:
    s=s.replace(destroy_old,destroy_new,1)
elif 'cleanupPrintWebView();\n        if (pendingPdfFile != null)' not in s:
    raise SystemExit('onDestroy print block missing')

p.write_text(s,encoding='utf-8')
print('patched-main-v160')
